#include <iostream>
#include <iomanip>

// Iterative factorial calculation (O(1) memory)
unsigned long long factorialIterative(unsigned int n) {
    unsigned long long result = 1;
    for (unsigned int i = n; i >= 1; --i) {
        result *= i;
    }
    return result;
}

// Recursive factorial calculation (O(n) stack frames)
unsigned long long factorialRecursive(unsigned int n) {
    if (n <= 1) {
        return 1; // Base case
    }
    return n * factorialRecursive(n - 1); // Recursive step
}

int main() {
    // Compare iterative and recursive results for 0 through 10
    for (unsigned int i = 0; i <= 10; ++i) {
        std::cout << std::setw(2) << i << "! = "
                  << std::setw(8) << factorialIterative(i) << " (iterative) | "
                  << std::setw(8) << factorialRecursive(i) << " (recursive)\n";
    }
    return 0;
}

#include <iostream>

// C++11 Scoped enum with explicit underlying type
enum class GameStatus : unsigned char {
    Continue,
    Won,
    Lost
};

// Function demonstrating automatic vs static storage duration
void trackGameState(GameStatus status) {
    // Automatic variable: recreated on each call
    int autoInvocationCount = 0;
    // Static local variable: initialized once, persists across calls
    static int totalGamesPlayed = 0;

    ++autoInvocationCount;
    ++totalGamesPlayed;

    std::cout << "Game #" << totalGamesPlayed
              << " [auto=" << autoInvocationCount << "]: ";

    switch (status) {
        case GameStatus::Continue:
            std::cout << "Game in progress.\n";
            break;
        case GameStatus::Won:
            std::cout << "Player WON!\n";
            break;
        case GameStatus::Lost:
            std::cout << "Player LOST.\n";
            break;
    }
}

int main() {
    trackGameState(GameStatus::Continue);
    trackGameState(GameStatus::Won);
    trackGameState(GameStatus::Lost);
    return 0;
}
